class Jp2FeatureTest {

    private fun fnv(d: ByteArray): Long {
        var h = -0x340d631b7bdddcdbL
        for (b in d) {
            h = h xor (b.toLong() and 0xFF)
            h *= 0x100000001b3L
        }
        return h
    }

    @Test
    fun everyFeatureDecodesToOpenJpegsSamples() {
        for ((name, data, hash) in Jp2FeatureFixtures.all) {
            val info = ImageKodec.probe(data)
            assertTrue(info.isDecodable, "$name: ${info.unsupportedReason}")
            val result = assertNotNull(JpxDecoder.decode(data), name)
            assertEquals(24, result.width, name)
            assertEquals(20, result.height, name)
            assertEquals(hash, fnv(result.pixelBytes), "$name differs from OpenJPEG")
            assertEquals(24 * 20, ImageKodec.decode(data).argb.size, name)
        }
    }
}
